
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All":"WITH raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.email_ AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask LEFT JOIN camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ LEFT JOIN camunda.act_hi_detail hidetail ON hidetail.name_ = ''userActivity'' AND hitask.assignee_ IS NOT NULL AND hitask.end_time_ IS NULL AND hidetail.proc_inst_id_ = hiproc.proc_inst_id_ LEFT JOIN camunda.act_id_user assignee ON assignee.id_ = hitask.assignee_ LEFT JOIN ui.webusermapping groupmembership ON cast(groupmembership.webuserid as text) = assignee.id_ and groupmembership.mappingtype = ''Group'' and groupmembership.mappingid != 1 and groupmembership.itenantid = :tenantid LEFT JOIN ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid LEFT JOIN ui.workflowmasters workflow on workflow.workflowkey = hiproc.proc_def_key_ and workflow.itenantid = :tenantid WHERE (CAST(hitask.end_time_ AS date) = :Date OR CAST(hidetail.time_ AS date) = :Date ) AND hitask.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hitask.assignee_ IS NOT NULL and hiproc.tenant_id_ = :tenantidstr ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(distinct org.groupname, '', '') AS \\"User Group\\", org.taskname as \\"Stage Name\\", count(distinct case when org.endtime is not null then org.taskid else null end) as \\"Cases Submitted\\", count(distinct case when org.endtime is null then org.taskid else null end) as \\"Claimed\\", count(distinct closedby.taskid) as \\"Total Cases - Closed\\", org.workflowname as \\"Workflow Name\\" FROM raw org LEFT JOIN raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) and closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname;",
    "Other":"WITH raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.email_ AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask LEFT JOIN camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ LEFT JOIN camunda.act_hi_detail hidetail ON hidetail.name_ = ''userActivity'' AND hitask.assignee_ IS NOT NULL AND hitask.end_time_ IS NULL AND hidetail.proc_inst_id_ = hiproc.proc_inst_id_ LEFT JOIN camunda.act_id_user assignee ON assignee.id_ = hitask.assignee_ LEFT JOIN ui.webusermapping groupmembership ON cast(groupmembership.webuserid as text) = assignee.id_ and groupmembership.mappingtype = ''Group'' and groupmembership.mappingid != 1 and groupmembership.itenantid = :tenantid LEFT JOIN ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid LEFT JOIN ui.workflowmasters workflow on workflow.workflowkey = hiproc.proc_def_key_ and workflow.itenantid = :tenantid WHERE (CAST(hitask.end_time_ AS date) = :Date OR CAST(hidetail.time_ AS date) = :Date ) AND hitask.proc_def_key_ = :CaseType AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hitask.assignee_ IS NOT NULL and hiproc.tenant_id_ = :tenantidstr ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(distinct org.groupname, '', '') AS \\"User Group\\", org.taskname as \\"Stage Name\\", count(distinct case when org.endtime is not null then org.taskid else null end) as \\"Cases Submitted\\", count(distinct case when org.endtime is null then org.taskid else null end) as \\"Claimed\\", count(distinct closedby.taskid) as \\"Total Cases - Closed\\", org.workflowname as \\"Workflow Name\\" FROM raw org LEFT JOIN raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) and closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname;"

}'::text WHERE
idashboardqueryid = 60 AND itenantid not in (select itenantid from ui.tenants where iorgid = 5 or iorgid = 0);

