UPDATE ui.dashboardquery SET
vcfilterparametersjson = '{"Basis":null,"DateRange":null,"CaseType":null,"StartStage":null,"EndStage":null, "CountLimit":null}'::text,
vcdashboardquery =  E'{
    "StartStage": {
